{
    int p, k = 0, m, i, j, t = 0, kk = 0, q = 0, qq, l = 0;

    for (i = 0; i < 24; i++)
    {
        k = 0;
        for (j = 0; j <= 59; j++)
        {
            pp.a[i] = i;
            pp.b[k] = j;
            k++;
        }
    }

    scanf("%d", &m);
    scanf("%d%d", &p, &k);
    t = p;

    for (qq = 0; qq < 22; qq++)
    {
        if (l > 0)
            t = 23;

        for (i = t; i >= 0; i--)
        {
            for (j = 0; j <= 59; j++)
            {
                if (i == p && pp.b[j] > k)
                    break;

                kk = p - i;
                q = kk * 60 + k - pp.b[j];

                if (l == 0 && i < p)
                    q = kk * 60 - pp.b[j] + k;

                if (l > 0)
                    q = (p + 24 - i) * 60 - pp.b[j] + k;

                if (q % m == 0 &&
